def test_centre_door_zero_step_only_original_confirmed(self):
    with self.assertRaisesRegex(ValueError,"centre 5"):
        layout_from_explicit_bureau(dun="yang",ju=1,hour_ganzhi="戊辰")

def test_fuyin_and_fanyin_tempo_do_not_cast_good_or_bad_vote(self):
    macro={
        "five_not_encounter":{
            "triggered":False,"hour_stem":"辛","day_stem":"甲"},
        "fuyin_fanyin":{
            "star":"伏吟","door":"反吟","pace":"混合"},
        "tempo":"mixed"}
    txt=render_first_stage_macro(macro)
    self.assertIn("伏吟主慢",txt)
    self.assertIn("反吟主快",txt)
    self.assertIn("缓急不自动等于吉凶",txt)
    for state,label,expected in (
        ("slow","伏吟","伏吟主慢"),
        ("fast","反吟","反吟主快")):
        macro["tempo"]=state
        macro["fuyin_fanyin"]={"star":label,"door":label}
        self.assertIn(expected,render_first_stage_macro(macro))

def test_cultural_not_clinical(self):
    for c in (self.c,self.e):
        s=next(x["text"] for x in c["source_sections"] if x["id"]=="90_review")
        self.assertIn("以上只作传统古籍象意参考",s)
        self.assertIn("不能据此判断真实病情",s)

def test_different_logic_is_preview_only_not_clinically_validated(self):
    for row,old,review in self.results:
        self.assertEqual(review["status"],"review_not_public")
        self.assertEqual(review["audit"]["actual_original_author_outcomes_not_used"],True)
    print("\n=== Four independent source-calculated review examples (not blind outcomes) ===")
    for n,(row,old,review) in enumerate(self.results,1):
        print("CASE",n,row["local_datetime"])
        print("BASELINE",old["reading_text"].split("最后断词：")[-1][:250].strip())
        print("MACRO",review["sections"][0]["text"])
        print("REVIEW",next(x["text"] for x in review["sections"]
                            if x["title"]=="全部证据合断"))
        print("GATES",review["audit"]["missing_source_predicates"],
              "LIFECYCLE_UNIQUE",len(review["audit"]["actual_stage_facts_unique"]))

